{
  "technical_and_design_decisions": [
    "Target codebase is the Spring XD 1.x distribution (Gradle-based build, Java 8, 'xd-container', HDFS sinks, Kafka transport, Reactor), as evidenced by the user stories (./gradlew dist/distZip, xd-container, Reactor 2.0.3, Kafka 0.8.x).",
    "U1 benchmarks will be implemented as repeatable, script-driven performance test scenarios so the 0.8.1 vs 0.8.2 Kafka comparison is reproducible; results will be captured in a written comparison report.",
    "U1 test matrix covers 3 payload types (baseline, Tuple, Serialized) x 2 Kafka versions (0.8.1, 0.8.2) x 3 sink topologies (In-Memory Transport > HDFS, Direct Binding Transport > HDFS, Kafka > HDFS).",
    "U2 Reactor upgrade is limited to the 2.0.3 version bump and the minimal code adaptations required for API/behavioral compatibility; no architectural refactoring.",
    "U3 JMX will be disabled by changing default configuration values (e.g., spring.jmx.enabled / XD JMX settings) while keeping an opt-in mechanism to re-enable it.",
    "U6 multi-instance support will be achieved via parameterized RPM init/service scripts with per-instance configuration directories, ports, log files, and PID files.",
    "U7/U8 documentation will be written in the existing project documentation format and toolchain (Asciidoc-style docs shipped with the project), including an index/anchors for per-job navigation.",
    "Build fixes (U4, U5) target the existing Gradle build without changing the overall build system."
  ],
  "assumptions": [
    "A single developer (the author) performs all work; estimates are effort in workdays, not calendar duration.",
    "The existing Spring XD codebase, source repository, and CI/build infrastructure are available and functional apart from the issues explicitly listed in U4/U5.",
    "Benchmark hardware is available, including a Hadoop/HDFS cluster and the ability to install Kafka 0.8.1 and 0.8.2 side by side for U1.",
    "Long-running benchmark executions are scripted; the estimated effort covers setup, execution monitoring, and analysis, and unattended run time is not counted as additional effort.",
    "U5 warning cleanup is limited to eliminating existing compiler and javadoc warnings; no functional refactoring beyond what is needed to remove warnings.",
    "RPM target platform is RHEL/CentOS-class Linux with standard init/systemd service management for U6.",
    "Documentation review and publication use the project's existing process; no new documentation tooling is introduced.",
    "No external dependencies (e.g., third-party approvals, upstream library releases) block the work."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1: Set up benchmark environment",
      "activity_description": "Provision and configure the performance test environment: side-by-side Kafka 0.8.1 and 0.8.2 brokers, HDFS cluster connectivity, and Spring XD runtime nodes needed for the benchmark topologies.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Implement benchmark payload scenarios",
      "activity_description": "Implement/configure the baseline, Tuple, and Serialized payload benchmark streams and the three sink topologies (In-Memory Transport > HDFS, Direct Binding Transport > HDFS, Kafka > HDFS), including metrics collection.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "U1: Execute benchmark test matrix",
      "activity_description": "Run the full test matrix (3 payload types x 2 Kafka versions x 3 sink topologies), monitor runs, and collect raw performance measurements.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "U1: Analyze results and produce comparison report",
      "activity_description": "Consolidate measurements, compare Kafka 0.8.1 vs 0.8.2 performance per topology and payload, and write the comparison report.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "U2: Upgrade Reactor dependency to 2.0.3",
      "activity_description": "Update Gradle dependency management to Reactor 2.0.3, align transitive dependencies, and resolve build-level conflicts.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6",
      "activity_name": "U2: Adapt code and regression-test Reactor upgrade",
      "activity_description": "Fix compilation issues and adapt code to Reactor 2.0.3 API/behavioral changes, then run unit/integration regression tests and a performance sanity check to confirm the optimizations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "U3: Disable JMX by default",
      "activity_description": "Change default configuration so JMX is turned off out of the box while preserving a documented opt-in property to re-enable it.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A8",
      "activity_name": "U3: Verify JMX-off behavior and update tests/docs",
      "activity_description": "Verify runtime behavior with JMX disabled, adjust affected tests, confirm expected throughput benefit, and update configuration documentation.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A9",
      "activity_name": "U4: Diagnose and fix dist/distZip build issues",
      "activity_description": "Reproduce and diagnose failures in the local ./gradlew dist and distZip targets, and fix the Gradle build scripts/configuration causing them.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "U4: Verify publish build pipeline",
      "activity_description": "Run clean dist/distZip and publish builds end-to-end to confirm the produced artifacts and publishing process work as expected.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A11",
      "activity_name": "U5: Clean up compiler warnings",
      "activity_description": "Fix compiler warnings across the codebase (deprecations, unchecked/raw types, unused imports, etc.) until compilation is warning-free.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A12",
      "activity_name": "U5: Clean up javadoc warnings and verify build output",
      "activity_description": "Fix javadoc warnings/errors across modules and verify the full build sysout is free of compiler and javadoc warnings.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A13",
      "activity_name": "U6: Design multi-instance xd-container layout",
      "activity_description": "Define the multi-instance approach: per-instance configuration directories, port allocation, log/PID file locations, and service naming conventions for RPM-installed xd-containers.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A14",
      "activity_name": "U6: Implement RPM packaging and init script changes",
      "activity_description": "Modify RPM packaging and init/service scripts so multiple xd-container instances can be installed, configured, started, and stopped independently on the same node/VM.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A15",
      "activity_name": "U6: Test multi-instance deployment",
      "activity_description": "Install the RPM on a target node, start multiple xd-container instances concurrently, and verify isolation, port handling, and lifecycle management.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A16",
      "activity_name": "U7: Document OOTB batch jobs with navigable sections",
      "activity_description": "Write/restructure documentation for the out-of-the-box batch jobs with per-job sections, anchors, and an index so users can jump directly to each job's details.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A17",
      "activity_name": "U8: Write analytics tab documentation",
      "activity_description": "Document the analytics tab and how to use its various widgets within a streaming pipeline, including examples and screenshots as appropriate.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A18",
      "activity_name": "Cross-cutting: Increment integration and release verification",
      "activity_description": "Integrate all changes, run the full build and system test suite, perform final sanity checks of the distribution artifacts, and prepare the increment for release.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 35
  }
}
